def the_header(case, data):
    """F1 — Deut 13:1 — THE HEADER'S SEAL IS A SECOND ENTRY (4:2's twin, the singular; THE LINE word_sealed REUSING adding_barred — 8b's and 10b's lesson); THE THREE GRAINS the shelf reads the seal at (the word's — the priests' blessing, Rosh Hashanah 28b carried; the count's — the four species and the fringes, Sukkah 34b, Menachot 41b-42a; the rite's — the mixed bloods, Mishnah Zevachim 8:10 with Zevachim 80a-81a); keep and do (82:2); the rebellious elder's fifth compartment (Sanhedrin 88b-89a carried); the festival's days (Chagigah 8b:11)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_headers_seal':
        ink('13:1', '"ALL THE WORD that I command you, it you shall keep to do; YOU SHALL NOT ADD TO IT NOR TAKE FROM IT" — "all the word that I command" the one seat %s; the singular pair %s against 4:2\'s plural %s and %s; the shared run with 4:2 %d (the only two seats of the pair); "keep to do" %s' % (P('את', 'כל', 'הדבר', 'אשר', 'אנכי', 'מצוה'), P('לא', 'תסף', 'עליו', 'ולא', 'תגרע', 'ממנו'), P('לא', 'תספו'), P('ולא', 'תגרעו'), SH(D13(1), ('Deut', 4, 2)), P('תשמרו', 'לעשות')))
        move('cold_run_obey_horeb (CALL) — OH.the_exhortation(add_nothing) = %s; OH.the_exhortation(diminish_nothing) = %s; the tape (the recon): add_nothing_commanded at Deut 4:1-8 (israel — FOUND by kind and first verse)' % (str(V(OH_ADD))[:70], str(V(OH_DIM))[:60]), "THE HEADER IS A SECOND ENTRY, NOT A NEW LAW — 4:2's cell holds the law (add_nothing, diminish_nothing, add_beside, add_out_of_its_time: the two parameters in the mitzva's time / out of it, with intent / without — Rosh Hashanah 28b:9, 23-24 carried); 13:1 restates it in the singular on 'all the word' — THE LINE word_sealed writes adding_barred on Israel a SECOND time (a reused effect is a second entry on the same ledger and moves an older count: CC3's 'adding_barred ONE' retyped TWO from the print BEFORE the tape — the grep decided seven count seats)")
        dat('THE LINE word_sealed — STATUTE by form, at the counter\'s own day %s after nations_cut_off_warned (the tape\'s last Deuteronomy 12 line), NO marker; THE WRITE adding_barred REUSED (the second entry; the first 4:1\'s: REUSE_SCAN %r); the readback row 13:1 VERBATIM in kind (add_nothing_commanded 4:1) with the cell by CALL' % (CLOCK['counter'], REUSE_SCAN))
        return out("the header's seal (13:1) — 'you shall not add to it nor take from it' = 4:2's law in the singular (the only two seats; seven tokens in order; OH.the_exhortation by CALL): THE LINE word_sealed REUSING adding_barred — a second entry on Israel at the chapter's own day; the readback row VERBATIM in kind", ['adding_barred'])
    if ask == 'the_three_grains':
        ink('13:1', '"you shall not add to it" — the seal read at three grains by the shelf: the WORD (the priests\' blessing, Numbers 6:23-27 %s), the COUNT (the four species, Leviticus 23:40 %s; the fringes, Numbers 15:38 %s), the RITE (the bloods\' placements, Leviticus 4-5 — "the horns of the altar" %s)' % (len(P('כה', 'תברכו')), len(P('פרי', 'עץ', 'הדר')), len(P('ציצת')), len(P('קרנת', 'המזבח'))))
        move('the Sifrei 82:3-5 (read whole at the reading); Sukkah 34b:3-4; Menachot 41b:12-42a:2; Mishnah Zevachim 8:10 with Zevachim 80a:1-4, 81a:1-4 (read whole at the docket); Rosh Hashanah 28b:10-13 and Sanhedrin 88b:14-89a:2 (carried from chapter 4\'s docket)', "THE THREE GRAINS — the word's: not a word added to the priests' blessing (82:5; 28b:10-13 the priest who adds a blessing); the count's: THE COUNTS FROM THE VERSE'S OWN NUMBERS — 'the fruit of a beautiful tree' ONE citron, 'branches of a date palm' written without the letter ONE, 'boughs of a dense-leaved tree' THREE, 'willows of the brook' TWO (R. Yishmael's baraita, Sukkah 34b:3), each species indispensable — the citron apart, the three bound (R. Eliezer, 34b:4); the fringes' strings four or three, no maximum but a minimum (Menachot 41b:12-42a:2); the rite's: the mixed bloods — one placement mixed with one, one; four with four, four; one with four — R. Eliezer: four (the added placements 'do not add'), R. Yehoshua: one (the omitted 'do not diminish'); THE ACTIVE GRAVER THAN THE PASSIVE (Mishnah Zevachim 8:10 at 80a:1; 80a:2-4, 81a:2-4 the arms; Eruvin 100a:18)")
        dat('the three grains a DATA row (the_three_grains — the word, the count, the rite; the counts (1, 1, 3, 2) from Sukkah 34b:3); the exam\'s persons the priest who adds a blessing, the one who takes a fifth species, the sprinkler of the mixed bloods — accepted against on the seal (the pair\'s two edges)')
        return out("the three grains (13:1) — the word's (the priests' blessing, 82:5; Rosh Hashanah 28b), the count's (the four species (1, 1, 3, 2) from the verse's own numbers — Sukkah 34b:3-4; the strings' minimum — Menachot 41b-42a), the rite's (the mixed bloods — Mishnah Zevachim 8:10, Zevachim 80a-81a: the active graver than the passive): the priest who adds a blessing accepted against the seal", ['accepted'])
    if ask == 'keep_and_do':
        ink('13:1', '"it you shall KEEP to DO" — the pair %s (13:1 and 24:8 the two seats); 4:2\'s "to keep the commandments" %s; 12:28\'s "observe and hear" %s' % (P('תשמרו', 'לעשות'), P('לשמר', 'את', 'מצות'), P('שמר', 'ושמעת')))
        move('the Sifrei 82:2, 85:3 (read whole at the reading)', "R. ELIEZER SON OF JACOB — 'keep' the prohibition, 'do' the positive command: a light commandment as a grave one (82:1 — Avot 2:1 at the footer, 96:7); 85:3 the same pair on 13:5's 'His commandments you shall keep' — the prohibition's guard the positive's twin")
        dat('keep and do a DATA row (R. Eliezer son of Jacob\'s rule at two seats — 82:2, 85:3); the exam\'s person the one who keeps the prohibition and neglects the command — the pair split: accepted against')
        return out("keep and do (13:1) — 'keep' the prohibition, 'do' the command (R. Eliezer son of Jacob, the Sifrei 82:2; 85:3 at 13:5): the one who keeps the prohibitions and neglects the commands accepted against the pair", ['accepted'])
    if ask == 'the_elders_not_adding':
        ink('13:1', '"you shall not add to it" — the elder\'s fifth compartment: "frontlets" %s (the tefillin\'s seats); 17:11\'s "you shall not turn from the word" ahead' % (U('לטטפת', 'לטוטפת', 'טטפת'),))
        move('Sanhedrin 88b:14-89a:2 (CREDITED whole from chapter 4\'s docket — carried with its verdict lines); Mishnah Sanhedrin 11:3; cold_run_obey_horeb (CALL) — OH.the_exhortation(add_beside) = %s' % (str(V(OH_BESIDE))[:60],), "THE REBELLIOUS ELDER'S NOT-ADDING — greater stringency in the scribes' words than in the Torah's: 'there is no mitzva of tefillin' exempt, 'FIVE COMPARTMENTS' liable (Mishnah 11:3 at 88b:14); liable only for a matter whose essence is Torah, whose explanation is the scribes', and WHICH CAN BE ADDED TO SO THAT THE ADDITION SPOILS IT (R. Elazar in R. Oshaya's name, 88b:15); the lulav by the binding, the fringe by the upper knot (88b:17-19, 89a:1); the fifth compartment MADE as one spoils, a fifth PLACED BESIDE stands alone (89a:2 — 4:2's cell's add_beside)")
        dat('the elder\'s not-adding a DATA row (carried whole from 2b\'s docket — 88b:14-89a:2); the exam\'s person the elder who rules five compartments — the addition that spoils: accepted against (Mishnah 11:3)')
        return out("the elder's not-adding (13:1) — five compartments made as one spoil the tefillin, a fifth beside stands alone (Sanhedrin 88b:14-89a:2 carried; Mishnah Sanhedrin 11:3; OH.the_exhortation('add_beside') by CALL): the elder who rules five compartments accepted against", ['accepted'])
    if ask == 'the_festivals_days':
        ink('13:1', '"you shall not add to it" — the festival\'s days: "seven days" in the book %s; the eighth day %s' % (len(P('שבעת', 'ימים', books=DT)), len(U('השמיני', books=DT))))
        move('Chagigah 8b:11 (read whole at the docket); cold_run_obey_horeb (CALL) — OH.the_exhortation(add_out_of_its_time) = %s' % (str(V(OH_TIME))[:70],), "THE FESTIVAL'S DAYS A TWO-ARM DISPUTE — ten animals set aside for the festival peace offering, five sacrificed the first day: Reish Lakish — the rest on another day complete the first, no 'do not add'; R. Yochanan — he stopped, another day is an added day (Chagigah 8b:11): the seal's reach on the festival's days; 4:2's cell's time arm (in the mitzva's time / out of it)")
        dat('the festival\'s days a DATA row (Chagigah 8b:11 — two arms recorded); the exam\'s person the one who completes his festival offerings on another day — Reish Lakish\'s arm: accepted (a recorded arm)')
        return out("the festival's days (13:1) — the rest of the festival offerings on another day: no added day (Reish Lakish) / an added day (R. Yochanan) — Chagigah 8b:11, 4:2's time arm by CALL: the one who completes on another day accepted (a recorded arm)", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_prophet_and_the_test(case, data):
    """F2 — Deut 13:2-6 — THE LINE prophet_test_declared writing false_prophet_hearing_barred (a BLOCK — the_signs_status a PARAMETER), tested_by_the_lord (a STATUS) and cleaving_commanded REUSED (the six verbs); THE DEATH at the case — the_prophets_death a PARAMETER (stoning / strangling; Mishnah Sanhedrin 11:1 the answer sheet's arm); evil_purged_from_the_midst NAMED at its first seat of nine; the false prophet's table (Sanhedrin 90a), the sign and the presumption (89b:6-7), Elijah at Carmel (Yevamot 90b), the oven of Akhnai (Bava Metzia 59b), the exemptions (86:1-2)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_prophet_and_the_dreamer':
        ink('13:2', '"WHEN A PROPHET ARISES AMONG YOU, OR A DREAMER OF A DREAM" — the clause %s; "a dreamer of a dream" %s; the dream\'s seats in the book %s (13:2, 4, 6 alone); 18:15\'s "a prophet from among you" %s ahead' % (P('כי', 'יקום', 'בקרבך', 'נביא'), P('חלם', 'חלום'), U('חלום', 'החלום', 'חלם', 'חולם', books=DT), P('נביא', 'מקרבך')))
        move('cold_run_beha (CALL) — BH.miriam(dreams) = %s; BH.miriam(dibbur) = %s; Sanhedrin 89b:6-7; Horayot 13a:12 (read whole at the docket); the Sifrei 83:1-2' % (str(V(BH_DREAMS))[:60], str(V(BH_DIBBUR))[:50]), "THE DREAM THE PROPHETS' CHANNEL — Numbers 12:6-8 by CALL ('in a vision I make Myself known, in a dream I speak to him'; Moses mouth to mouth — the Sifrei 83:2; Sifrei Bamidbar 103); THE PROPHET'S FORMS ARE MOSES' — 'thus said', part delivered, part fulfilled (83:1); THE SIGN AND THE PRESUMPTION — how does one know the prophet is a prophet? he gives a sign; ONE ALREADY PRESUMED NEEDS NONE (89b:6 — Micah gave none; 89b:7 Isaac at Moriah, Israel at Carmel); 13:2 the definition of a prophet (Horayot 13a:12 — the prophet's precedence over the high priest)")
        dat('THE LINE prophet_test_declared — STATUTE by form at the counter\'s day %s, NO marker; the readback row 13:2 SUPPLIED AS A LAW (the first seat — the line\'s own; the kin by CALL: BH.miriam); the dream\'s three seats a DATA row; the Genesis dream lines (came_in_a_dream, dreamed, dream_told) by kind DATA rows' % (CLOCK['counter'],))
        return out("the prophet and the dreamer (13:2) — the dream the prophets' channel (Numbers 12:6-8 by CALL; the Sifrei 83:2), the prophet's forms Moses' (83:1); the sign the title's proof and the presumed prophet exempt from it (Sanhedrin 89b:6-7): THE LINE prophet_test_declared at the counter's day; the readback row SUPPLIED AS A LAW", ['accepted'])
    if ask == 'the_sign_and_the_wonder':
        ink('13:2-3', '"and gives you A SIGN OR A WONDER, and the sign and the wonder come to pass" — "a sign or a wonder" %s (the "or" the chapter\'s); "the sign and the wonder" %s; the wonder\'s seats in the Bible %d; 1 Kings 13:3\'s "this is the sign" the one two-token kin %s' % (P('אות', 'או', 'מופת'), P('האות', 'והמופת'), len(U('מופת', 'ומופת', 'מופתים', 'ומופתים', 'מפתים', 'ומפתים', 'המופת', 'והמופת', 'המפתים', 'והמפתים', 'ומפתיו', 'ומופתיו', 'מפתי', 'למופת', 'מופתי', 'ומפתי', 'מופתו')), KINC[2][:1]))
        move('the Sifrei 83:4-5 (read whole at the reading); Sanhedrin 89b:6 (read whole at the docket)', "THE SIGN IN THE HEAVENS AND THE WONDER ON THE EARTH — 'a sign' in the heavens (Genesis 1:14's lights), 'a wonder' on the earth (Gideon's fleece, Judges 6:36-40 — 83:4-5); 1 Kings 13:3's sign at Jeroboam's altar the run's case (the altar split, the ashes poured); the sign the prophet's credential, not the law's proof")
        dat('the sign and the wonder a DATA row (the heavens and the earth — 83:4-5; 1 Kings 13:3 the kin); the exam\'s person the prophet whose sign comes to pass and who preaches nothing against the Torah — heeded: accepted')
        return out("the sign and the wonder (13:2-3) — the sign in the heavens, the wonder on the earth (the Sifrei 83:4-5; 1 Kings 13:3 the one two-token kin); the sign the credential: the prophet whose sign comes to pass and preaches nothing against the Torah accepted", ['accepted'])
    if ask == 'the_signs_status':
        ink('13:3-4', '"saying: LET US GO AFTER OTHER GODS which you have not known, and let us serve them — YOU SHALL NOT HEARKEN to the words of that prophet or that dreamer of the dream" — "let us go after other gods" %s; "let us go" the cohortative in the Torah %s; "you shall not hearken to the words" %s; "other gods which you have not known" (pl.) %s' % (P('נלכה', 'אחרי', 'אלהים', 'אחרים'), len(U('נלכה', books=T)), P('לא', 'תשמע', 'אל', 'דברי', 'הנביא', 'ההוא'), P('אלהים', 'אחרים', 'אשר', 'לא', 'ידעתם')))
        move('the Sifrei 84:1-4 (read whole at the reading); Sanhedrin 90a:10, 90a:11 (read whole at the docket); the Rambam\'s Introduction 5:3; cold_run_covenant_at_horeb (CALL) — CH.the_second_word(no_other_gods) = %s; the parameter the_signs_status = %s' % (str(V(CH_OTHER))[:50], sorted(SIGNS)), "THE SIGN'S STATUS A PARAMETER WITH TWO ARMS — R. Yosei HaGelili: the Torah gave the false prophet DOMINION in idolatry's matter — the sign REAL, and even if he stops the sun in mid-sky, do not heed him (84:1 at 90a:10; R. Abbahu in R. Yochanan's name: 'violate the Torah provisionally' is heeded, EXCEPT for idolatry); R. Akiva: Heaven forfend that the sun be stopped for the wicked — a false prophet works no miracle; the warning is for one who BEGAN TRUE and fell, Hananiah son of Azzur (84:2 at 90a:11; Jeremiah 28 the run's case); either arm: THE HEARING BARRED — the sign not examined once idolatry is preached (the Rambam's Introduction 5:3); not one who retracts, not one suspected in hindsight (84:3-4); the seducers' one formula — 13:3, 13:7, 13:14 each other's closest kin (KINC: %s)" % (KINC[3][:1],))
        dat('THE WRITE false_prophet_hearing_barred — a BLOCK on israel_people at the counter\'s day (DE2, DE4): NO CELL ANYWHERE held the false prophet\'s hearing (the recon\'s scan; the one database on Israel %r): the code\'s hole compiled; the readback rows 13:3 VARIANT in kind (calf_made Exod 32:4 — "these are your gods" the seducers\' formula in the run; the second word by CALL) and 13:4 SUPPLIED AS A LAW WITH THE WRITE; the parameter\'s two arms recorded, not resolved' % (SEDUCERS_SCAN,))
        return out("the sign's status (13:3-4) — a PARAMETER: R. Yosei HaGelili's dominion (the sign real, the sun stopped, do not heed — Sanhedrin 90a:10) / R. Akiva's fallen prophet (Hananiah — 90a:11); either arm THE HEARING BARRED: THE WRITE false_prophet_hearing_barred — a BLOCK on Israel at the chapter's own day; the readback row 13:4 SUPPLIED AS A LAW with its write", ['false_prophet_hearing_barred'])
    if ask == 'the_lord_is_testing_you':
        ink('13:4', '"FOR THE LORD YOUR GOD IS TESTING YOU, to know whether you love the LORD your God with all your heart and with all your soul" — the participle\'s one seat %s; the root\'s Deuteronomy seats %s; "to know whether you are" %s; "with all your heart and with all your soul" (pl.) %s; 11:13 the closest kin %s' % (P('כי', 'מנסה', 'יהוה', 'אלהיכם', 'אתכם'), [(s, x) for s, x, _ in LEMT('5254', books=DT)], P('לדעת', 'הישכם'), P('בכל', 'לבבכם', 'ובכל', 'נפשכם'), KINC[4][:2]))
        move('the tape (the recon): tested at Gen 22:1 (the-lord — FOUND by kind and first verse; god_fearing_known the verdict\'s status); cold_run_mamre (CALL) — MM.moriah = %s; cold_run_good_land (CALL) — GL.the_way_of_forty_years(the_test) = %s; cold_run_hear_o_israel (CALL) — HI.the_test_and_the_right(you_shall_not_test) = %s; the Sifrei 84:5' % (V(MM_MORIAH), str(V(GL_TEST))[:50], str(V(HI_TEST))[:50]), "THE TESTING'S SEATS — Genesis 22:1's 'God tested Abraham' THE FIRST SEAT, on the tape (the readback row 13:4 by kind; MM.moriah by CALL — Isaac at Moriah on the prophet's presumption, Sanhedrin 89b:7); 8:2 and 8:16's forty years 'to test you, to know what was in your heart' (GL by CALL — the same clause 'to know'); 6:16's 'you shall not test the LORD' THE MIRROR — Israel testing God (HI by CALL; test_barred ONE UNMOVED); 84:5 the verse whole — the sign the test's instrument, the love the test's object (11:13's plural heart and soul the closest kin, nine tokens in order)")
        dat('THE WRITE tested_by_the_lord — a STATUS on israel_people at the counter\'s day (DE2, DE4): the participle\'s one seat in the Bible; tested_the_lord (Exod 14:11 — the counter STATUS on Israel) and test_barred the mirror DATA rows; the exam\'s person the one who follows the sign against the commandment — the test failed: accepted against')
        return out("the LORD is testing you (13:4) — the participle's one seat; Genesis 22:1's tested the first seat on the tape (MM.moriah by CALL), 8:2 and 8:16 by CALL (GL), 6:16's test_barred the mirror (HI): THE WRITE tested_by_the_lord — a STATUS on Israel at the chapter's own day; the one who follows the sign against the commandment accepted against", ['tested_by_the_lord'])
    if ask == 'the_six_verbs':
        ink('13:5', '"AFTER THE LORD YOUR GOD YOU SHALL WALK, and Him you shall fear, and His commandments you shall keep, and His voice you shall obey, and Him you shall serve, AND TO HIM YOU SHALL CLEAVE" — six clauses each one seat %s; the cleaving\'s Deuteronomy seats %s; 13:5\'s tokens %d against 10:20\'s %d and 6:13\'s %d' % ([P('אחרי', 'יהוה', 'אלהיכם', 'תלכו'), P('ואתו', 'תיראו'), P('ואת', 'מצותיו', 'תשמרו'), P('ובקלו', 'תשמעו'), P('ואתו', 'תעבדו'), P('ובו', 'תדבקון')], [(s, x) for s, x, _ in LEMT('1692', books=DT)], LEN('Deut', 13, 5), LEN('Deut', 10, 20), LEN('Deut', 6, 13)))
        move('cold_run_second_tablets (CALL) — ST.the_god_of_gods_and_the_stranger(fear_serve_cleave_swear) = %s; ST.the_stations_and_the_death(walk_after_his_attributes) = %s; cold_run_hear_o_israel (CALL) — HI.the_four_duties(fear_serve_swear) = %s; the tape (the recon): cleaving_commanded at Deut 10:20-22 and cloud_lifted at Num 10:11 (FOUND by kind and first verse); cold_run_erection (CALL) — ER.cloud(journeys) = %s; the Sifrei 85:1-6' % (str(V(ST_FOUR))[:50], str(V(ST_ATTR))[:50], str(V(HI_FEAR))[:40], str(V(ER_JOURN))[:40]), "THE SIX VERBS AFTER THE FOUR AND THE THREE — 10:20's fear, serve, cleave, swear (the first entry, cleaving_commanded on the tape — the readback row 13:5 EXPANDED in kind); 6:13's three by CALL; 85:1 THE FIRST VERB IS THE CLOUD — 'after the LORD you shall walk' = after the cloud (Numbers 9-10; cloud_lifted 10:11 — a RUN CITATION inside a law); 85:2 His fear upon you; 85:3 keep the prohibition; 85:4 'HIS VOICE' THE VOICE OF HIS PROPHETS — the true prophet's channel seated in the false prophet's chapter (Yevamot 90b:5 — 18:15 ahead); 85:5 serve Him in His Torah and His sanctuary; 85:6 separate from idolatry and cleave; Sotah 14a's 'walk after His attributes' at its own cell (ST by CALL): THE WRITE cleaving_commanded REUSED — a second entry on Israel")
        dat('THE WRITE cleaving_commanded REUSED — a second entry on israel_people at the counter\'s day (DE2: 10:20\'s and 13:5\'s; the literals DB2, DC6, Q27, Q30 retyped ONE -> TWO); the readback row 13:5 EXPANDED in kind (cleaving_commanded 10:20) with the cells by CALL; the six verbs a DATA row (the_six_verbs — the counts (6, 4, 3))')
        return out("the six verbs (13:5) — walk, fear, keep, obey, serve, cleave: 10:20's four (ST by CALL; cleaving_commanded on the tape — the readback row EXPANDED) and 6:13's three (HI by CALL); the first verb the cloud (85:1 — cloud_lifted a run citation), 'His voice' the prophets' (85:4): THE WRITE cleaving_commanded REUSED — a second entry on Israel at the chapter's own day", ['cleaving_commanded'])
    if ask == 'the_false_prophets_table':
        ink('13:3, 13:6', '"let us go after other gods … and let us serve them" — the object idolatry; "shall be put to death" %s (13:6 the chapter\'s one "yumat"); the four deaths\' census by CALL' % (P('יומת'),))
        move('Sanhedrin 90a:2, 90a:5, 90a:6 (read whole at the docket); Mishnah Sanhedrin 11:5-6 (credited, read whole here); cold_run_sanctions (CALL) — SA.census(strangled) = %s; SA.census(stoned) = %s' % (str(V(SA_STRANG))[:50], str(V(SA_STONED))[:50]), "THE FALSE PROPHET'S TABLE — a prophet who abolishes the ESSENCE of another commandment: strangled, all agree; keeps PART and voids part: exempt, all agree (R. Shimon's arm); a true prophet's TEMPORARY nullification: heed him (90a:2, 90a:5); the baraita's three rows — to abolish a matter of the Torah, strangled; part, R. Shimon exempts; IDOLATRY — 'worship it today and tomorrow nullify it', ALL AGREE LIABLE (90a:6 — idolatry's zero tolerance, a day); Mishnah 11:5-6 — the one who prophesies what he did not hear, what was not said to him, in another's name, in idolatry's name even if he ruled the law rightly")
        dat('the false prophet\'s table a DATA row (the_false_prophets_table — the essence, the part, the hour, idolatry a day); the exam\'s persons the prophet with a true sign who preaches idolatry for a day (put_to_death — the parameter\'s default arm) and the prophet who keeps part and voids part of another commandment (EXEMPT — 90a:5)')
        return out("the false prophet's table (13:3, 13:6) — the essence abolished: strangled; the part: exempt; the hour: heeded; IDOLATRY EVEN FOR A DAY: liable, all agree (Sanhedrin 90a:2-6; Mishnah Sanhedrin 11:5-6; SA.census by CALL): the prophet who keeps part and voids part exempt", ['exempt'])
    if ask == 'the_prophets_death':
        ink('13:6, 13:11', '"and that prophet or that dreamer of the dream SHALL BE PUT TO DEATH … to THRUST you from the way" / "for he sought to THRUST you from the LORD" — "to thrust" the two seats %s; "shall be put to death" the one seat %s; "you shall stone him" at 13:11 %s' % ([(s, x) for s, x, _ in LEMT('5080', books=DT) if s in ('Deut 13:6', 'Deut 13:11')], P('יומת'), P('וסקלתו', 'באבנים', 'ומת')))
        move('the Sifrei 86:6, 90:2 (read whole at the reading); Sanhedrin 89b:15-21 (read whole at the docket); Mishnah Sanhedrin 11:1 (credited whole, carried); the Rambam\'s Introduction 5:2; cold_run_sanctions (CALL) — SA.census(strangled) = %s; the parameter the_prophets_death = %s' % (str(V(SA_STRANG))[:60], sorted(DEATH)), "THE MODE A PARAMETER — STONING: the Sifrei's majority and the Rabbis at 89b:15-19 by the analogy of 'thrust' (13:6 / 13:11 — I2, checked in MIDDOT.md: as the inciter is stoned, so the false prophet; 90:2 the analogy run back); STRANGLING: R. Shimon (86:6) and MISHNAH SANHEDRIN 11:1's list of the strangled — THE ANSWER SHEET'S ARM (an unspecified death in the Torah is strangling, 89b:20-21; the Rambam's Introduction 5:2 'witnesses testifying, strangled'); the runner's case takes the answer sheet's arm — put_to_death ('mode per the compiled law': strangling) beside evil_purged_from_the_midst; the reason the a fortiori from the plotting witness (86:3 — Mishnah Makkot 1:4-6, 1:6 carried)")
        dat('THE CASE\'S WRITES — put_to_death (REUSED — the mode per the parameter\'s default arm, strangling) and evil_purged_from_the_midst (THE FORMULA\'S FIRST SEAT OF NINE) on the exam\'s false prophet (DE6 — never on the tape); the parameter\'s two arms recorded, not resolved (the_prophets_death a DATA row); the readback row 13:6 SUPPLIED AS A LAW (the case\'s)')
        return out("the prophet's death (13:6) — a PARAMETER: stoning (the Sifrei's majority by I2 on 'thrust' with 13:11; the Rabbis at Sanhedrin 89b:15-19) / strangling (R. Shimon; Mishnah Sanhedrin 11:1 — the answer sheet's arm; the Rambam 5:2): the false prophet who preaches idolatry put to death (the answer sheet's mode) and the evil purged from the midst — THE FORMULA'S FIRST SEAT", ['put_to_death', 'evil_purged_from_the_midst'])
    if ask == 'the_exodus_formula_with_redeeming':
        ink('13:6, 13:11', '"who brought you out of the land of Egypt AND REDEEMED YOU from the house of bondage" — the formula with redeeming the one seat %s; "who redeemed you" %s; 13:11\'s "who brought you out of the land of Egypt, out of the house of bondage" %s (5:6\'s six tokens in order); the redeeming root in the book %s' % (P('המוציא', 'אתכם', 'מארץ', 'מצרים', 'והפדך', 'מבית', 'עבדים'), U('והפדך', 'פדך', 'ופדך'), P('המוציאך', 'מארץ', 'מצרים', 'מבית', 'עבדים'), [(s, x) for s, x, _ in LEMT('6299', books=DT)]))
        move('cold_run_covenant_at_horeb (CALL) — CH.the_first_tablet(the_first_word) = %s; cold_run_not_righteousness (CALL) — NR.the_intercession = %s; cold_run_seven_nations (CALL) — SN.the_holy_people(brought_out_redeemed) = %s; the Sifrei 86:4-5, 90:3' % (str(V(CH_FIRST))[:50], str(V(NR_INTER))[:50], str(V(SN_REDEEMED))[:50]), "THE EXODUS FORMULA WITH REDEEMING — 5:6's preamble by CALL ('I am the LORD your God who brought you out of the land of Egypt, out of the house of bondage' — 13:11 verbatim in kind), 9:26's redeeming by CALL ('Your people and Your inheritance which You redeemed'), 7:8's by CALL; 'EVEN HAD HE NO CLAIM ON YOU but that He brought you out of Egypt, enough' (86:4-5; 90:3 the same at 13:11) — the seducer's rebellion against the Redeemer")
        dat('the exodus formula with redeeming a DATA row (the three cells by CALL — the preamble, the intercession, the holy people); "rebellion" the noun\'s two Torah seats (13:6, 19:16 — 189:1 reading each by the other; Hananiah\'s sentence Jeremiah 28:16) a DATA row for 19:16\'s sitting; the exam\'s person the one who says the Redeemer has no claim — accepted against (86:4)')
        return out("the exodus formula with redeeming (13:6, 13:11) — 5:6's preamble (CH by CALL), 9:26's redeeming (NR by CALL), 7:8's (SN by CALL); 'even had He no claim but that, enough' (the Sifrei 86:4-5, 90:3): the one who denies the Redeemer's claim accepted against", ['accepted'])
    if ask == 'the_evil_purged':
        ink('13:6', '"AND YOU SHALL PURGE THE EVIL FROM YOUR MIDST" — the formula\'s nine seats in the book %s (13:6 the first; 17:12 and 22:22 "from Israel"); the plural form nowhere %s; "the evil" in the chapter %s' % (P('ובערת', 'הרע'), P('ובערתם', 'הרע'), [(v, x) for v in range(1, 20) for x in W13(v) if x in ('הרע', 'רע', 'הרעה')]))
        move('the Sifrei 86:10 (read whole at the reading); the registry (the design): NO effect naming the purge before this sitting — purge_deadline the leaven\'s timer and purge_commanded Jacob\'s (Genesis 35:2) the homographs; Onkelos 13:6 "the doer of evil"', "THE PURGE FORMULA'S FIRST SEAT OF NINE — 'purge the DOER of evils from Israel' (86:10): the person removed, the evil with him; the effect NAMED HERE — evil_purged_from_the_midst, a body effect written on the condemned person at the exam's case, REUSED at 17:7, 17:12, 19:19, 21:21, 22:21, 22:22, 22:24, 24:7 ahead (each a second entry — the compile's gain from naming the effect at its first seat, 8b's lesson turned forward)")
        dat('THE CASE\'S WRITE evil_purged_from_the_midst — THE FORMULA\'S FIRST SEAT (DE6: absent from every ledger before the exam\'s case, written on the case\'s persons after; never on the tape); the nine seats a DATA row on the DB (the_purge_formulas_seats — DE8); the homographs a DATA row; the exam\'s person the seducer removed — the evil purged')
        return out("the evil purged (13:6) — THE FORMULA'S FIRST SEAT OF NINE (the DB's seats all in the book; 86:10 the doer removed): evil_purged_from_the_midst NAMED here — a body effect on the condemned person at the case, reused at the eight seats ahead; the homographs (purge_deadline, purge_commanded) named, not counted", ['evil_purged_from_the_midst'])
    if ask == 'the_exemptions':
        ink('13:6', '"for he spoke rebellion against the LORD" — "spoke" the perfect %s; the noun "rebellion" %s (13:6 and 19:16 the Torah\'s two)' % ([(x, m) for x, m in wm('Deut', 13, 6) if x == 'דבר'], [(s, x) for s, x, _ in LEMT('5627', books=T)]))
        move('the Sifrei 86:1-2 (read whole at the reading); Sanhedrin 90a:5 (read whole at the docket)', "THE EXEMPTIONS — not one coerced, not one misled (86:1-2: 'for he spoke' — of his own will, knowing); the prophet who keeps part and voids part of another commandment within his mandate — exempt, all agree (90a:5); the one who retracts before the fence (84:3; 67a:5 for the inciter)")
        dat('the exemptions a DATA row (duress and error — 86:1-2); the exam\'s person the prophet who spoke under duress — EXEMPT (86:1)')
        return out("the exemptions (13:6) — 'for he spoke': of his own will, knowing — not the coerced, not the misled (the Sifrei 86:1-2); the part-keeper exempt (Sanhedrin 90a:5): the prophet who spoke under duress exempt", ['exempt'])
    if ask == 'elijah_at_carmel':
        ink('13:5', '"and His voice you shall obey" — "His voice" %s (the Sifrei 85:4: the voice of His prophets); 18:15\'s "to him you shall listen" ahead %s' % (P('ובקלו', 'תשמעו'), P('אליו', 'תשמעון')))
        move('Yevamot 90b:5, 90b:6, 90b:10-11 (read whole at the docket); Sanhedrin 89b:7; the Sifrei 70:3 (chapter 12 — the prophet\'s exception at 12:13); the Sifrei 85:4', "ELIJAH AT CARMEL HEEDED — 'to him you shall listen' (18:15): even if the prophet says TRANSGRESS ONE OF THE TORAH'S COMMANDMENTS, like Elijah at Carmel (an offering outside under the penalty of karet — excision), for the requirement of the hour: heed him (90b:5); there it is different — a positive command overriding a prohibition; and SAFEGUARDING A MATTER is different: Elijah acted to keep Israel from idolatry (90b:6 — the chapter's own matter; the court's emergency stoning on the same ground, 90b:10-11); the presumed prophet (89b:7); 12:13's prophet's exception the same case at the place's law")
        dat('Elijah at Carmel a DATA row (the temporary uprooting — 85:4\'s "His voice" the prophets\'; the true prophet\'s channel seated in the false prophet\'s chapter); the exam\'s person Elijah at Carmel — EXEMPT (Yevamot 90b:5-6; the false prophet\'s table\'s third row, 90a:2)')
        return out("Elijah at Carmel (13:5) — 'His voice' the voice of His prophets (the Sifrei 85:4): the true prophet's TEMPORARY uprooting heeded — 'to him you shall listen' and safeguarding a matter (Yevamot 90b:5-6; Sanhedrin 90a:2): Elijah at Carmel exempt", ['exempt'])
    if ask == 'the_oven_of_akhnai':
        ink('13:2-3', '"a sign or a wonder … and the sign and the wonder come to pass" — the sign\'s force in a legal dispute; 30:12\'s "it is not in heaven" ahead %s' % (P('לא', 'בשמים', 'הוא'),))
        move('Bava Metzia 59b (read whole at the docket — 59b:12-15 the convert\'s rows carried from 8b; the oven\'s rows read whole here)', "THE OVEN OF AKHNAI — R. Eliezer's carob tree, the stream, the walls of the study house, the heavenly voice; R. Yehoshua: 'it is not in heaven' (30:12) — the law by the majority (Exodus 23:2), no sign decides a legal dispute; the Holy One smiled: 'My children have defeated Me' — THE SIGN NOT DECISIVE IN LAW, the chapter's own principle at its aggadic seat")
        dat('the oven of Akhnai a DATA row (the sign not decisive in law — Bava Metzia 59b); the exam\'s person the sage who rules by the carob tree — the majority stands: accepted against')
        return out("the oven of Akhnai (13:2-3) — the carob, the stream, the walls, the heavenly voice, and 'it is not in heaven': the sign not decisive in law (Bava Metzia 59b): the sage who rules by the sign accepted against", ['accepted'])
    if ask == 'the_established_prophet':
        ink('13:2', '"when a prophet arises among you" — the prophet\'s definition; "prophet" in the chapter %s' % ([(v, x) for v in range(1, 20) for x in W13(v) if x in ('נביא', 'הנביא')],))
        move('Sanhedrin 89b:6-7 (read whole at the docket); Horayot 13a:12; Mishnah Sanhedrin 11:5 (the one who forgoes his prophecy)', "THE ESTABLISHED PROPHET NEEDS NO SIGN — how does one know the prophet is a prophet, to be punished for forgoing his word? he gives a sign; Micah gave none: one already presumed a prophet needs no sign (89b:6); else how did Isaac submit at Moriah, how did Israel rely on Elijah at Carmel? the presumed prophet is different (89b:7); 13:2 the definition (Horayot 13a:12)")
        dat('the established prophet a DATA row (the sign and the presumption); the exam\'s person the presumed prophet who gives no sign — heeded: accepted (89b:6)')
        return out("the established prophet (13:2) — one already presumed a prophet needs no sign (Sanhedrin 89b:6-7 — Micah, Isaac at Moriah, Israel at Carmel): the presumed prophet who gives no sign accepted", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_inciter(case, data):
    """F3 — Deut 13:7-12 — THE LINE inciter_law_declared writing pity_barred REUSED (the five prohibitions against the standing duties; the court's rule inverted) and israel_hears_and_fears (THE FORMULA'S FIRST SEAT — the_execution_timing a PARAMETER); the inciter's kin (87:4-11), the entrapment (Mishnah 7:10; Sanhedrin 67a), the fifteen utterances, the hand first (13:10), the stoning's rite (13:11 — the wood-gatherer's cell by CALL), seclusion (Kiddushin 80b)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_inciters_kin':
        ink('13:7', '"WHEN YOUR BROTHER, THE SON OF YOUR MOTHER, or your son or your daughter or THE WIFE OF YOUR BOSOM or YOUR FRIEND WHO IS AS YOUR OWN SOUL entices you" — "your brother the son of your mother" %s; "the wife of your bosom" %s; "your friend as your own soul" %s; "as your own soul" in the Bible %s; 13:7\'s tokens %d, the register singular %s' % (P('אחיך', 'בן', 'אמך'), P('אשת', 'חיקך'), P('רעך', 'אשר', 'כנפשך'), U('כנפשך', 'כנפשו'), LEN('Deut', 13, 7), NUM[7]))
        move('the Sifrei 87:4-11 (read whole at the reading); Sanhedrin 85b:2 (read whole at the docket)', "THE INCITER'S KIN AN INCLUSION TABLE — 'your brother' by the father, 'the son of your mother' the mother's; 'your son' and 'your daughter' of any kind; 'the wife of your bosom' the betrothed and the married; 'your friend' the convert; 'as your own soul' — THE FATHER (87:4-11: the closest kin named so that the farthest is included); the son as the court's agent against his inciting father — 'neither spare nor conceal him' (85b:2 — Rabba bar Rav Huna and R. Yishmael's school)")
        dat('THE LINE inciter_law_declared — STATUTE by form at the counter\'s day %s, NO marker; the readback row 13:7 SUPPLIED AS A LAW (the first seat — the line\'s own; the second word by CALL); the inclusion table a DATA row (the_inciters_kin); the exam\'s person the son who strikes his inciting father — the agent permitted: accepted (85b:2)' % (CLOCK['counter'],))
        return out("the inciter's kin (13:7) — the brother by the father, the mother's son, the son and the daughter of any kind, the betrothed and the married, the convert, THE FATHER in 'as your own soul' (the Sifrei 87:4-11): THE LINE inciter_law_declared at the counter's day; the son who strikes his inciting father accepted (Sanhedrin 85b:2)", ['accepted'])
    if ask == 'entice_two_senses':
        ink('13:7', '"entices you" — the Torah\'s ONE token of the root %s (the Bible\'s %d); "in secret" %s (13:7 the chapter\'s; 27:15, 24 and 28:57 the book\'s others); 1 Kings 21:25\'s "incited" Jezebel\'s the run\'s' % ([s for s, _, _ in LEMT('5496', books=T)], len(LEMT('5496')), U('בסתר', books=DT)))
        move('the Sifrei 87:1-3, 87:12-13 (read whole at the reading); Kiddushin 80b:6 (read whole at the docket)', "'ENTICE' TWO SENSES — error and provocation (87:1-2: 'entices' as at 1 Samuel 26:19 'if the LORD has incited you', as at Job 36:16); 'in secret' — the inciter speaks in secret, the Torah answers in public (87:12); Israel's disgrace (87:13); SECLUSION DERIVED FROM 'THE SON OF YOUR MOTHER' — a man may be secluded with his mother, not with any other woman (Kiddushin 80b:6; Sanhedrin 21b, Avodah Zarah 36b) — the link rows' second use of the verse")
        dat('"entice" two senses a DATA row; the seclusion a DATA row (Kiddushin 80b:6 — the verse\'s second use on the shelf); the exam\'s person the one enticed in error — the inciter\'s guilt the same: accepted')
        return out("entice, two senses (13:7) — error and provocation (the Sifrei 87:1-2); in secret answered in public (87:12); seclusion from 'the son of your mother' (Kiddushin 80b:6): the one enticed in error accepted — the inciter's guilt the same", ['accepted'])
    if ask == 'the_entrapment':
        ink('13:7, 13:9', '"entices you IN SECRET" / "nor shall you spare NOR CONCEAL HIM" — "you shall not conceal" %s; the concealed witnesses the inciter\'s own procedure' % (P('ולא', 'תכסה', 'עליו'),))
        move('Mishnah Sanhedrin 7:10 at Sanhedrin 67a:2-5, 67a:12-13 (read whole at the docket); cold_run_sanctions (CALL) — SA.molech(concealed) = %s; the Sifrei 89:5' % (str(V(SA_CONC))[:50],), "THE INCITER'S MISHNAH — an ordinary person, not a prophet; inciting an individual, not a multitude; his speech 'there is an idol in such a place, it eats so, drinks so, does good so, harms so' (67a:2); THE ENTRAPMENT — for all liable to death the court hides no witnesses, EXCEPT THE INCITER (67a:3, 67a:12); spoken to two — they are his witnesses, NO FOREWARNING NEEDED, they stone him; to one — 'I have friends who want this, tell them too' (67a:4); THE STAGE — a candle lit for him in an inner room, the witnesses in the dark outer room seeing and hearing; 'say what you said to me in seclusion'; 'how can we forsake our God in Heaven for wood and stones?' — RETRACTS: good; 'IT IS OUR DUTY': stoned (67a:5, 67a:13); ben Setada hanged at Lod on Passover eve (67a:15)")
        dat('the entrapment\'s script a DATA row (the_entrapment — the lit room, the dark room, the question, the two answers); the exam\'s persons the inciter entrapped in the lit room who says "it is our duty" (stoned) and the inciter who retracts before the fence (EXEMPT — 67a:5)')
        return out("the entrapment (13:7, 13:9) — the only capital case with hidden witnesses (Sanhedrin 67a:3, 12): the lit inner room, the dark outer room, 'say what you said to me in seclusion'; the retraction's exemption, 'it is our duty' stoned (67a:5, 13); no forewarning to two hearers (67a:4): the inciter who retracts before the fence exempt", ['exempt'])
    if ask == 'the_fifteen_utterances':
        ink('13:7, 13:14', '"saying: LET US GO AND SERVE other gods" — "let us go and serve" %s (13:7 and 13:14 — the brother and the city one speech); "let us go after" %s (13:3 the prophet\'s)' % (P('נלכה', 'ונעבדה', 'אלהים', 'אחרים'), P('נלכה', 'אחרי', 'אלהים', 'אחרים')))
        move('the Sifrei 91:3 (read whole at the reading); Sanhedrin 67a:6 (read whole at the docket); Mishnah Sanhedrin 7:6 (credited, carried); cold_run_ordinances (CALL) — OR.capital(service_architecture) = %s' % (str(V(OR_SERV))[:60],), "THE FIFTEEN UTTERANCES — 'I shall worship' / 'I shall go and worship' / 'let us go and worship' — and so for sacrificing, burning incense, pouring a libation, bowing: THREE FORMS BY FIVE SERVICES, a table at the answer sheet (67a:6 — 91:3); the four services of death (Mishnah 7:6 — sacrificing, burning, libation, bowing; embracing, kissing, sweeping the prohibition alone — 91:4's honors not capital; OR.capital('service_architecture') by CALL)")
        dat('the fifteen utterances a DATA row (the_fifteen_utterances — a three-by-five table: (3, 5, 15)); the honors not capital a DATA row (Mishnah 7:6 carried); the exam\'s person the inciter who says "I shall go and burn incense" — one of the fifteen: stoned (the case\'s)')
        return out("the fifteen utterances (13:7, 13:14) — three forms by five services (Sanhedrin 67a:6; the Sifrei 91:3): 'I shall worship', 'I shall go and worship', 'let us go and worship' — by worship, sacrifice, incense, libation, bowing (OR.capital by CALL); the honors not capital (Mishnah 7:6): the inciter's speech a table", ['accepted'])
    if ask == 'the_five_prohibitions':
        ink('13:9', '"YOU SHALL NOT CONSENT TO HIM NOR HEARKEN TO HIM, NOR SHALL YOUR EYE PITY HIM, NOR SHALL YOU SPARE NOR CONCEAL HIM" — five negations in one verse %s; "your eye shall not pity" the book\'s five %s; "spare" the Torah\'s two %s (Exodus 2:6 Pharaoh\'s daughter; 1 Samuel 15:3 Saul\'s the run\'s); "you shall not consent" %s' % ([x for x in W13(9) if x in NEG], P('לא', 'תחוס', 'עינך') + P('ולא', 'תחוס', 'עינך'), [(s, x) for s, x, _ in LEMT('2550', books=T)], P('לא', 'תאבה', 'לו')))
        move('cold_run_seven_nations (CALL) — SN.because_you_hear(consume_no_pity) = %s; cold_run_holiness (CALL) — HO.conduct(great_rule) = %s, HO.conduct(blood) = %s; cold_run_ordinances (CALL) — OR.courts(enemy_ox) = %s; the Sifrei 89:1-5; Sanhedrin 36b:5' % (str(V(SN_PITY))[:50], str(V(HO_RULE))[:50], str(V(HO_BLOOD))[:50], str(V(OR_ENEMY))[:50]), "THE FIVE PROHIBITIONS EACH AGAINST A STANDING DUTY — 'you shall not consent to him' against 'love your neighbor as yourself' (89:1 — Leviticus 19:18, HO.conduct('great_rule') by CALL); 'nor hearken to him' against the enemy's ass (89:2 — Exodus 23:5, OR.courts('enemy_ox') by CALL); 'nor shall your eye pity him' — 7:16's clause on the nations REUSED on the inciter (SN.because_you_hear by CALL — pity_barred's second entry); 'nor spare' against 'you shall not stand by your neighbor's blood' (89:3 — Leviticus 19:16, HO.conduct('blood') by CALL); 'nor conceal' — the defense barred and the silence barred (89:4-5); the Sanhedrin seats no cruel man, but for the inciter compassion is withheld (36b:5 — Tosefta 7:5)")
        dat('THE WRITE pity_barred REUSED — a second entry on israel_people at the counter\'s day (DE2: 7:16\'s and 13:9\'s; the literals CQ6, DC6, Q17, Q30 retyped ONE -> TWO); the readback row 13:9 EXPANDED by CALL (the five duties); the five prohibitions a DATA row (the_five_prohibitions); the exam\'s person the judge who pleads for the inciter — the defense barred: accepted against (89:4)')
        return out("the five prohibitions (13:9) — each against a standing duty: the love of the neighbor (Leviticus 19:18 — HO by CALL), the enemy's ass (Exodus 23:5 — OR by CALL), the pity (7:16 — SN by CALL), the neighbor's blood (Leviticus 19:16 — HO by CALL), the defense and the silence (the Sifrei 89:1-5): THE WRITE pity_barred REUSED — a second entry on Israel at the chapter's own day; the judge who pleads for the inciter accepted against", ['pity_barred'])
    if ask == 'the_courts_rule_inverted':
        ink('13:9-10', '"nor shall you spare nor conceal him; but KILL, YOU SHALL KILL HIM" — "kill, you shall kill" the doubled verb %s (the infinitive absolute %s); the court\'s ordinary rule by CALL' % (P('הרג', 'תהרגנו'), [(x, m) for x, m in wm('Deut', 13, 10) if m and m.endswith('a')]))
        move('the Sifrei 89:6-7 (read whole at the reading); Sanhedrin 33b:7, 36b:5, 43a:21, 61b:3-11, 63b:7 (read whole at the docket); Mishnah Sanhedrin 4:1 (credited, carried) at 40a:9-14; cold_run_ordinances (CALL) — OR.courts(acquitted_retried) = %s, OR.courts(begin_from_side) = %s, OR.courts(dissenter) = %s' % (str(V(OR_ACQ))[:50], str(V(OR_SIDE))[:40], str(V(OR_DISS))[:40]), "THE COURT'S RULE INVERTED AT ITS SEAT — the ordinary rule: the acquitted not retried, the convicted brought back to acquit; the deliberation opened for acquittal; no death by a majority of one (Mishnah 4:1; 40a:9-14 — OR.courts by CALL); FOR THE INCITER THE OPPOSITE — 'neither spare nor conceal him' (13:9): convicted not brought back to acquit, acquitted brought back to convict (89:6-7; Rav Shimi bar Ashi at 33b:7 with Rav Kahana's second source 'kill, you shall kill him' 13:10); the court's compassion withheld from the inciter alone (36b:5); Ulla's proof from 13:9 (43a:21); THE CONSENT ALONE — the enticed who says 'I will' liable? (61b:3-11 — Rav Yosef, Abaye, Rava: 13:9's 'you shall not consent' — the consent the liability's ground, the near teach the far); 13:12 the inciter's warning (63b:7)")
        dat('the court\'s rule inverted a DATA row (the_courts_rule_inverted — the ordinary rule by CALL, the inversion\'s two sources); the exam\'s person the enticed who heard and DID NOT CONSENT — EXEMPT (61b:3-9: the consent the liability\'s ground)')
        return out("the court's rule inverted (13:9-10) — the acquitted brought back to convict, the convicted not brought back to acquit (the Sifrei 89:6-7; Sanhedrin 33b:7 with 13:9 and 13:10 its two sources; Mishnah Sanhedrin 4:1's ordinary rule by CALL — OR.courts); the consent alone the liability (61b:3-11): the enticed who did not consent exempt", ['exempt'])
    if ask == 'the_hand_first':
        ink('13:10', '"YOUR HAND SHALL BE ON HIM FIRST to put him to death, and the hand of all the people AFTERWARD" — "your hand first" %s; 17:7\'s twin %s ahead; "and the hand of all the people" %s (13:10, 17:7); "afterward" the Torah\'s two %s' % (P('ידך', 'תהיה', 'בו', 'בראשונה'), P('תהיה', 'בו', 'בראשנה', 'להמיתו'), P('ויד', 'כל', 'העם'), U('באחרנה', 'באחרונה', books=T)))
        move('the Sifrei 89:8 (read whole at the reading); cold_run_lev24 (CALL) — L24.talion() = %s (the blasphemer\'s chapter; sentence_declared\'s hands_laid at Leviticus 24:14 the tape\'s field); cold_run_sanctions (CALL) — SA.molech(who_stones) = %s' % (str(V(L24_TALION))[:50], str(V(SA_WHO))[:50]), "THE HAND FIRST — the enticed's own commandment to be first, any man's after (89:8); 17:7 'the hand of the witnesses shall be on him first' the twin ahead (the witnesses there, the enticed here — one who heard); Leviticus 24:14's 'all who heard shall lay their hands on his head' by CALL (the blasphemer — the hearers' hands); Leviticus 20:2's 'the people of the land shall stone him' (SA.molech by CALL — who stones)")
        dat('the readback row 13:10 VARIANT by CALL (MK.capital_procedure; L24 the hearers\' hands); the hand first a DATA row (13:10 and 17:7 the two seats of "first" and "afterward" on a hand); the exam\'s person the enticed who lets another cast the first stone — accepted against (89:8)')
        return out("the hand first (13:10) — the enticed's own commandment, the people's after (the Sifrei 89:8; 17:7's witnesses the twin ahead; Leviticus 24:14's hands laid by CALL — L24; Leviticus 20:2's people by CALL — SA.molech): the enticed who lets another cast the first stone accepted against", ['accepted'])
    if ask == 'the_stoning_rite':
        ink('13:11', '"AND YOU SHALL STONE HIM WITH STONES THAT HE DIE" — the clause %s; "with stones that he die" %s (13:11, 21:21); the root of stoning in the book %s against Leviticus\'s and Numbers\' %s (THE TWO VERBS OF STONING — 21:21 both); "for he sought to thrust you" %s' % (P('וסקלתו', 'באבנים', 'ומת'), P('באבנים', 'ומת'), [s for s, _, _ in LEMT('5619', books=DT)], [s for s, _, _ in LEMT('7275', books=('Lev', 'Num'))], P('בקש', 'להדיחך')))
        move('cold_run_mekoshesh (CALL) — MK.capital_procedure(stones_and_a_stone) = %s; MK.capital_procedure(stoning) = %s; MK.capital_procedure(warning) = %s; the tape (the recon): stoned_as_commanded at Lev 24:23 and Num 15:36 (FOUND by kind and first verse); the Sifrei 90:1-2; Sifrei Bamidbar 113-114; Sanhedrin 54b:5' % (str(V(MK_STONES))[:60], str(V(MK_STONING))[:50], str(V(MK_WARN))[:40]), "THE STONING'S RITE IS THE WOOD-GATHERER'S CELL — 'with stones': the stones, and if he died by the one stone, enough (90:1 — the Sifrei 90:1's stones and the stone are in the engine already: MK.capital_procedure('stones_and_a_stone') by CALL); 'for he sought to thrust you' — the analogy run back to the false prophet (90:2 — the_prophets_death's stoning arm); Sifrei Bamidbar 114 — the custody for all liable, 'stone him' this case; 113 — R. Yitzchak's a fortiori from idolatry (I1 — the forewarning); the stoning derived from 'kill' by 'shall be put to death' (54b:5); the two verbs of stoning a DATA row (Deuteronomy's four seats, Leviticus's and Numbers' — 21:21 both)")
        dat('THE CASE\'S WRITES — stoned (REUSED — the blasphemer\'s, the wood-gatherer\'s: the counts UNMOVED, DE5) and evil_purged_from_the_midst on the exam\'s inciter (DE6); the readback row 13:11 VARIANT in kind (stoned_as_commanded Lev 24:23) with the cell by CALL; the two verbs of stoning a DATA row on the DB (DE8)')
        return out("the stoning's rite (13:11) — the stones and the stone (the Sifrei 90:1 — MK.capital_procedure by CALL: the wood-gatherer's cell holds it); stoned_as_commanded on the tape (the readback row VARIANT); the two verbs of stoning (Deuteronomy's against Leviticus's and Numbers'): the inciter who says 'it is our duty' stoned and the evil purged from the midst", ['stoned', 'evil_purged_from_the_midst'])
    if ask == 'the_execution_timing':
        ink('13:12', '"AND ALL ISRAEL SHALL HEAR AND FEAR, and shall not do again such an evil thing as this in your midst" — the formula\'s first seat with the paragogic nun %s; the four seats %s; "shall not do again" %s (13:12; 19:20 without the letter); "such an evil thing" %s' % (P('ישמעו', 'ויראון'), P('ישמעו', 'ויראון') + P('ישמעו', 'ויראו'), P('ולא', 'יוספו', 'לעשות'), P('כדבר', 'הרע', 'הזה')))
        move('the Sifrei 91:1-2 (read whole at the reading); Mishnah Sanhedrin 11:4 (credited, carried) with Sanhedrin 89a:6; Tosefta Sanhedrin 11:3 (read whole at the docket); the parameter the_execution_timing = %s' % (sorted(TIMING),), "THE EXECUTION'S TIMING A PARAMETER — R. Akiva: the inciter is KEPT to the Festival and executed before all Israel, 'and all Israel shall hear and fear' (91:1; Mishnah 11:4 — the rebellious elder, the false prophet and the inciter; 89a:6 the four brought up to Jerusalem for the Festival; Tosefta 11:3 naming the chapter's three); R. Yehuda: AT ONCE — no delay of judgment, the courts notified in writing (91:2); the verdict's own delay to the next day (40a:11) the court's, not the execution's")
        dat('THE WRITE israel_hears_and_fears — a STATUS on israel_people at the counter\'s day (DE2, DE4, DE6 — its value naming 13:12 as the first of four); the readback row 13:12 SUPPLIED AS A LAW WITH THE WRITE; the timing\'s two arms recorded (the_execution_timing a DATA row); the exam\'s person the court that executes the inciter at once — R. Yehuda\'s arm: accepted (a recorded arm)')
        return out("hear and fear (13:12) — THE FORMULA'S FIRST SEAT OF FOUR (13:12, 17:13, 19:20, 21:21): THE WRITE israel_hears_and_fears — a STATUS on Israel at the chapter's own day; the execution's timing a PARAMETER — kept to the Festival (R. Akiva; Mishnah Sanhedrin 11:4) / at once with the notice (R. Yehuda) — the Sifrei 91:1-2: the court that executes at once accepted (a recorded arm)", ['israel_hears_and_fears'])
    return out('no verdict in span', [FX.NONE])
